<?php $pendingCount=count(array_filter($rows,fn($r)=>$r['situacao']==='aguardando_conferencia')); $valorBusca='0.00';$foraBusca=0;foreach($rows as $r){$valorBusca=bcadd($valorBusca,$r['valor_bem']??'0.00',2);if(in_array($r['situacao'],['em_estoque','manutencao','baixado'],true))$foraBusca++;} ?>
<p class="muted">Patrimônios associados às compras pelo cadastro de imobilizado do SGA. Registros importados aguardam conferência física antes de entrar no estoque ou serem movimentados.</p>
<section class="metrics project-metrics"><article><p>Ativos nesta busca</p><strong><?=count($rows)?></strong></article><article><p>Aguardando conferência</p><strong><?=$pendingCount?></strong></article><article><p>Custo dos itens nesta busca</p><strong class="currency">R$ <?=number_format((float)$valorBusca,2,',','.')?></strong><small>Inclui baixados, se presentes no filtro</small></article><article><p>Fora de uso nesta busca</p><strong><?=$foraBusca?></strong><small>Estoque, manutenção ou baixados</small></article></section>
<form method="get" action="/ativos" class="toolbar"><input name="q" value="<?=e($qAtivos)?>" placeholder="Patrimônio, produto ou código da compra SGA" aria-label="Pesquisar ativos"><select name="situacao" aria-label="Situação de uso dos equipamentos"><?php foreach([''=>'Todas as situações','alocado'=>'Em uso · alocados','fora_uso'=>'Fora de uso · estoque, manutenção e baixados','em_estoque'=>'Em estoque','manutencao'=>'Em manutenção','baixado'=>'Baixados','aguardando_conferencia'=>'Aguardando conferência'] as $value=>$label): ?><option value="<?=$value?>" <?=($estadoAtivos??'')===$value?'selected':''?>><?=e($label)?></option><?php endforeach; ?></select><select name="escopo" aria-label="Escopo dos ativos"><option value="">Escopo atual da consulta</option><option value="todos" <?=$escopoTodos?'selected':''?>>Todo o histórico importado</option></select><button>Pesquisar</button><a class="button secondary" href="/ativos">Limpar</a></form><p class="small muted"><?=$escopoTodos?'Exibindo todo o histórico importado, inclusive de requisitantes e centros de custo removidos da consulta.':'Exibindo somente bens das compras dos requisitantes e centros de custo configurados em Integração (qualquer categoria). Bens sem compra de origem sempre aparecem.'?></p>
<section class="panel table-panel"><table><thead><tr><th>Patrimônio / compra</th><th>Custo de aquisição</th><th>Situação</th><th>Local e CC confirmados</th><th>Referência do SGA</th><th>Responsável</th><th>Ação</th></tr></thead><tbody>
<?php foreach($rows as $r): $sga=$sgaPorAtivo[$r['id']]??null; ?><tr><td><strong><?=e($r['patrimonio'])?></strong><small><?=e($r['produto'])?><br>Empresa <?=e($r['empresa_patrimonio'])?> · Compra SGA #<?=e($r['origem_item_id'])?><br>Série: <?=e($r['serie']?:'Não informada')?></small></td><td><strong><?=$r['valor_bem']===null?'Não identificado':'R$ '.number_format((float)$r['valor_bem'],2,',','.')?></strong><small><?=e($r['base_custo'])?></small><?php if($r['alerta_custo']): ?><small class="danger">Valor de origem exige revisão</small><?php endif; ?></td><td><?=$pill($r['situacao'])?><?php if($sga && (!$sga['origem_presente'] || $sga['situacao']==='conflito')): ?><small class="danger"><?=e($sga['motivo']?:'Conferir origem')?></small><?php endif; ?></td><td><?=e($r['local_nome']?:'Não conferido')?><small><?=e($r['cc_nome']?:'CC atual não conferido')?></small></td><td><?php if($sga): ?><small><?=e($sga['nome_bem'])?><br>Local cadastrado: <?=e($sga['localizacao_sga']?:'Não informado')?><br>CC cadastrado: <?=e($sga['centro_custo_sga']?:'Não informado')?><br>Bem #<?=e($sga['bem_id'])?> · Item #<?=e($sga['imobilizado_item_id'])?><br>Fonte: <?=e($sga['fonte']==='sga'?'Consulta direta SGA':'Levantamento salvo')?></small><?php else: ?><small>Cadastro local</small><?php endif; ?></td><td><?=e($r['responsavel']?:'—')?></td><td>
<?php if($can && $r['situacao']==='aguardando_conferencia'): ?><details><summary>Conferir patrimônio</summary><form action="/patrimonio-conferir" method="post" class="stack"><?=csrf()?><input type="hidden" name="ativo_id" value="<?=$r['id']?>"><p class="small">Confirme a etiqueta <?=e($r['patrimonio'])?> e o bem fisicamente. Esta ação incorpora uma unidade ao inventário.</p><label>Número de série<input name="serie" maxlength="150"></label><label>Local físico atual<select name="local_id" required><?=options($locais)?></select></label><label>Centro de custo atual<select name="cc_id" required><?=options($ccs)?></select></label><label>Registro da conferência<textarea name="motivo" required maxlength="500"></textarea></label><button>Confirmar conferência</button></form></details>
<?php elseif($can && $r['situacao']!=='baixado'): ?><details><summary>Movimentar</summary><form action="/mover-ativo" method="post" class="stack"><?=csrf()?><input type="hidden" name="ativo_id" value="<?=$r['id']?>"><input type="hidden" name="chave_operacao" value="<?=$operationKey()?>"><label>Operação<select name="tipo"><option value="alocacao">Alocar a responsável</option><option value="transferencia">Transferir local / CC</option><option value="devolucao">Devolver ao estoque</option><option value="manutencao">Enviar à manutenção</option><option value="baixa">Baixar patrimônio</option></select></label><label>Local de destino<select name="local_id" required><?=options($locais,$r['local_atual_id'])?></select></label><label>Centro de custo de destino<select name="cc_id" required><?=options($ccs,$r['centro_custo_atual_id'])?></select></label><label>Responsável<select name="responsavel_id"><?=options($responsaveis,$r['responsavel_atual_id'])?></select></label><label>Motivo<textarea name="motivo" required maxlength="500"></textarea></label><button>Registrar movimentação</button></form></details><?php endif; ?>
</td></tr><?php endforeach; ?></tbody></table><?php if(!$rows): ?><p class="empty">Nenhum ativo encontrado nesta busca.</p><?php endif; ?></section>
<section class="panel"><h2>Pendências de associação</h2><p class="small muted">Números com mais de uma compra candidata não são atribuídos automaticamente. Confira a nota e escolha a linha correta. O cadastro físico atual não é alterado por uma nova coleta.</p><?php if(!$pendenciasSga): ?><p class="muted">Nenhuma pendência de associação.</p><?php endif; ?><?php foreach($pendenciasSga as $s): $payload=json_decode($s['payload_json'],true)?:[]; $candidates=json_decode($s['candidatos_json'],true)?:[]; ?><details><summary>Patrimônio <?=e($s['patrimonio']?:'Sem número')?> · <?=e($s['nome_bem'])?> · <?=e($s['situacao'])?></summary><p><?=e($s['motivo'])?></p><p class="small">Nota <?=e($payload['numero_nota']??'')?> · Compras candidatas: <?=e(implode(', ',$candidates))?></p><?php if($can && !$s['ativo_id'] && $s['origem_presente'] && $s['patrimonio']): ?><form method="post" action="/patrimonio-associar" class="stack"><?=csrf()?><input type="hidden" name="patrimonio_sga_id" value="<?=$s['id']?>"><label>Compra correta<select name="origem_item_id" required><option value="">Selecione após conferir</option><?php foreach($candidates as $candidate): ?><option value="<?=e($candidate)?>">Compra SGA #<?=e($candidate)?></option><?php endforeach; ?></select></label><label>Justificativa<textarea name="motivo" required maxlength="500"></textarea></label><button>Associar à compra</button></form><?php endif; ?></details><?php endforeach; ?></section>
<section class="panel table-panel"><h2>Bens do imobilizado sem número de patrimônio (<?=count($semNumeroSga)?>)</h2><p class="small muted">Estes bens existem no imobilizado do SGA para compras do escopo, mas estão sem número de patrimônio. Por isso não viram ativo: a aplicação não inventa número. Para incluí-los, registre o número no SGA e sincronize de novo.</p><?php if(!$semNumeroSga): ?><p class="muted">Nenhum bem sem número no escopo.</p><?php else: ?><table><thead><tr><th>Bem / descrição no imobilizado</th><th>Nota fiscal</th><th>Valor de aquisição</th><th>Compra SGA</th><th>CC do bem</th></tr></thead><tbody><?php foreach($semNumeroSga as $s): $pl=json_decode((string)$s['payload_json'],true)?:[]; ?><tr><td><strong><?=e($s['nome_bem'])?></strong><small><?=e(preg_replace('/\s*\[NCM:.*$/','',(string)($pl['descricao_imobilizado']??'')))?></small></td><td><?=e($pl['numero_nota']??'—')?></td><td><?=isset($pl['valor_aquisicao_imobilizado'])&&is_numeric($pl['valor_aquisicao_imobilizado'])?'R$ '.number_format((float)$pl['valor_aquisicao_imobilizado'],2,',','.'):'Não informado'?></td><td>#<?=e(implode(', #',$pl['compras_candidatas']??[$pl['origem_item_id']??'']))?></td><td><?=e($s['centro_custo_sga']?:'—')?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></section>
<p class="small muted">As próximas sincronizações em Integração Minerion também consultam o imobilizado e associam novos números com vínculo único. Registros sem número não recebem um patrimônio inventado.</p>
